#include "gtest/gtest.h"
#include "../../tests/gtest/test_population_test_fixture.hpp"

namespace {

// CatchAtAge_EvaluateAgeingError
// IO correctness
// Test that a fleet's ageing error moves its expected age composition to
// observed ages in each year and that a fleet without ageing error is
// unchanged
TEST_F(CAAInitializeTestFixture, EvaluateAgeingErrorHandlesCorrectInput) {
  this->InitializeCAA();
  std::shared_ptr<fims_popdy::Fleet<double>> with_error = population->fleets[0];
  std::shared_ptr<fims_popdy::Fleet<double>> without_error =
      population->fleets[1];

  // 1 matrix per year. Year 0 has no ageing error. In later years each age is
  // read correctly with probability 0.7 and 1 year too old with probability
  // 0.3, and the plus group is always read correctly. The matrix is not
  // symmetric, so a transposed matrix would move fish to younger ages.
  const int matrix_size = n_ages * n_ages;
  with_error->ageing_error.resize(n_years * matrix_size);
  for (int year = 0; year < n_years; year++) {
    for (int true_age = 0; true_age < n_ages; true_age++) {
      int i_diagonal = year * matrix_size + true_age * n_ages + true_age;
      if (year == 0 || true_age == n_ages - 1) {
        with_error->ageing_error[i_diagonal] = 1.0;
      } else {
        with_error->ageing_error[i_diagonal] = 0.7;
        with_error->ageing_error[i_diagonal + 1] = 0.3;
      }
    }
  }

  // In every year, all fish are age 5 and 100 were sampled.
  const int all_fish_age = 5;
  for (auto& fleet : population->fleets) {
    auto& dq_fleet =
        catch_at_age_model->GetFleetDerivedQuantities(fleet->GetId());
    for (int year = 0; year < n_years; year++) {
      dq_fleet["agecomp_proportion"][year * n_ages + all_fish_age] = 1.0;
      dq_fleet["agecomp_expected"][year * n_ages + all_fish_age] = 100.0;
    }
  }

  catch_at_age_model->evaluate_ageing_error();

  auto& dq_with =
      catch_at_age_model->GetFleetDerivedQuantities(with_error->GetId());
  auto& dq_without =
      catch_at_age_model->GetFleetDerivedQuantities(without_error->GetId());
  for (int year = 0; year < n_years; year++) {
    for (int age = 0; age < n_ages; age++) {
      int i_age_year = year * n_ages + age;
      double unchanged_proportion = (age == all_fish_age) ? 1.0 : 0.0;
      double expected_proportion = unchanged_proportion;
      if (year > 0 && age == all_fish_age) {
        expected_proportion = 0.7;
      } else if (year > 0 && age == all_fish_age + 1) {
        expected_proportion = 0.3;
      }
      EXPECT_NEAR(dq_with["agecomp_proportion"][i_age_year],
                  expected_proportion, 1e-12);
      EXPECT_NEAR(dq_with["agecomp_expected"][i_age_year],
                  100.0 * expected_proportion, 1e-10);

      EXPECT_EQ(dq_without["agecomp_proportion"][i_age_year],
                unchanged_proportion);
      EXPECT_EQ(dq_without["agecomp_expected"][i_age_year],
                100.0 * unchanged_proportion);
    }
  }
}

}  // namespace
